// mixins/shareNoParamMixin.js
// 引入封装好的userShare接口
import {
    userShare
} from '@/api/demo';

export default {
    // 1. 监听「分享给朋友」（不配置title/path，仅调无参接口）
    onShareAppMessage() {
        return {
            success: async () => {
                await this._callUserShareApi(); // 调用无参接口
            },
            fail: (err) => {
                console.error('分享给朋友触发失败', err);
            }
        };
    },

    // 2. 监听「分享到朋友圈」（不配置title/path，仅调无参接口）
    onShareTimeline() {
        this._callUserShareApi(); // 朋友圈无success，直接调接口
        return {}; // 不配置title/path，用默认值
    },

    methods: {
        // 核心：调用你的无参接口userShare（适配你的request封装）
        async _callUserShareApi() {
            try {
                // 调用基于你request封装的userShare接口
                const res = await userShare();
                console.log('userShare接口调用成功', res);
            } catch (err) {
                console.error('userShare接口调用失败', err);
                // 接口失败不弹提示，避免影响用户体验
            }
        }
    }
};